-- TP-05: registro de importaciones de precios y textos, y los dos campos de pospago por servicio que trae el JSON.
-- Solo agrega. ofrecer_pospago nace en true para no cambiar lo que ya existe; precio_pospago_propio nace vacío.

ALTER TABLE "procesos" ADD COLUMN IF NOT EXISTS "ofrecer_pospago" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "procesos" ADD COLUMN IF NOT EXISTS "precio_pospago_propio" NUMERIC(15,2);

CREATE TABLE IF NOT EXISTS "importaciones_catalogo" (
  "id_importacion" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "usuario" VARCHAR(150) NOT NULL,
  "fecha" TIMESTAMP NOT NULL DEFAULT now(),
  "total_servicios" INTEGER NOT NULL,
  "ids_proceso" VARCHAR(500) NOT NULL,        -- p. ej. «1,2,5»
  "payload" TEXT NOT NULL                      -- el JSON tal como se importó
);
